// `claudinite.packVersions`; `computeVendorSet` returns the version of every declared
// pack and the writer stamps the lot in the same pass. The hazard is the opposite of
// "unversioned", and worse:
//
//   IT STAMPS EVERY DECLARED PACK AT THE NEWEST VERSION, whether or not the records
//   between were ever applied. `migrationApplies` is `want > have`, so the moment the
//   stamp reaches the record's own version the record stops applying — not for this
//   cycle, but forever. A member converged this way ends up CLAIMING a version whose
//   shape it was never migrated into, and nothing downstream can tell the difference,
//   because the stamp is the only thing that remembers.
//
// At version zero that is exactly right, and it is what an install means: no older
// state exists, so there is nothing to skip. Run it over a repo that already has a
// stamp and the same behaviour silently burns that repo's pending records — which is
// why `planInstall` refuses an already-installed pack rather than treating this as an
// optimisation (see the exit note at the bottom of `main`, which had this right).
//
// One runner, one stamp. The skills describe intent and hand-offs; the arithmetic of
// what version a repo is now at belongs here, where the update flows read it from.
async function main() {
  const argv = process.argv.slice(2);
  const flag = (name) => { const i = argv.indexOf(name); return i === -1 ? null : argv[i + 1] ?? null; };
  const targetRoot = flag('--target') ?? process.env.CLAUDINITE_REPO_ROOT ?? process.cwd();
  const dryRun = argv.includes('--dry-run');
  const consumed = new Set(['--target', targetRoot, '--dry-run', '--delivery', flag('--delivery')]);
  const ids = argv.filter((a) => !a.startsWith('--') && !consumed.has(a));
  if (!ids.length) {
    console.error('install: name at least one pack id — `node install.mjs --target <dir> <pack-id>…`');
    process.exit(1);
  }

  const r = await installPacks(targetRoot, ids, { dryRun, delivery: flag('--delivery') ?? 'auto-merge' });
  for (const i of r.install ?? []) console.log(`install: ${i.id} → version ${i.version ?? 'unversioned'}`);
  for (const f of r.refused ?? []) console.log(`install: REFUSED ${f.id} — ${f.why}`);
  for (const s of r.seeded ?? []) console.log(`install: seeded ${s}`);

  // Loud, and last before the status line: these are the steps the adoption cannot
  // take, and the adopting session owes each one its own tracking issue.
  if ((r.handover ?? []).length) {
    console.log(`\ninstall: ${r.handover.length} step(s) only a human can do — open a tracking issue for these:`);
    for (const h of r.handover) {
      console.log(`  [ ] (${h.pack}) ${h.step}`);
      if (h.breaks) console.log(`        while off: ${h.breaks}`);
      if (h.done) console.log(`        done when: ${h.done}`);
    }
    console.log('');
  }
  console.log(`install: ${r.status} — ${r.detail}`);

  // A refusal is not a partial success. `planInstall` refuses a pack whose engine is
  // too old, an unknown id, and a pack already installed (that is an UPDATE, and
  // running an install over it would restamp the repo to the newest version while
  // skipping every record in between). Exiting 0 there would let a caller's `&&`
  // chain carry on as if the pack were adopted.
  if (r.status === NEEDS_HUMAN || (r.refused ?? []).length) process.exit(1);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e) => { console.error(`install failed: ${e.message}`); process.exit(1); });
}
